-- =============================================================================
-- 484 — LE CAHIER D'EXERCICES DE 4E (partie 3)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/4e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 484 --niveau 4e --fichiers emc.jumelles,espagnol.jumelles-2 --suffixe 3 > supabase/contenu/484_exercices_4e_3.sql
--
-- 48 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   emc.jumelles            30 exercices · 10 chapitres
--   espagnol.jumelles-2     18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('65e0d920-687e-574f-8faf-8c28b3d725cd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La loi de 1905","competence":"analyser-texte","situation":"La loi du 9 décembre 1905 est le texte fondateur de la laïcité. Voici ses deux idées, présentées dans un extrait adapté.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"La loi de séparation (adaptée)","blocs":["La République garantit la liberté de conscience et le libre exercice des cultes.","Elle ne reconnaît, ne salarie et ne subventionne aucun culte."],"source":"D’après la loi du 9 décembre 1905 (texte adapté pour l’exercice)."}],"questions":[{"enonce":"Touche les trois verbes qui expriment le principe de séparation de l’État et des cultes.","aide":"Ils sont dans la deuxième phrase.","type":"zone","document":"loi","multiple":true},{"enonce":"Associe chaque pilier de la laïcité à ce qu’il garantit.","aide":"Chaque pilier a un mot-clé dans son nom.","type":"association","gauche":[{"id":"g0","texte":"Liberté de conscience"},{"id":"g1","texte":"Séparation"},{"id":"g2","texte":"Égalité"}],"droite":[{"id":"d0","texte":"Tous égaux devant la loi, quelle que soit leur croyance"},{"id":"d1","texte":"Croire, ne pas croire, changer, pratiquer ou non"},{"id":"d2","texte":"L’État ne reconnaît ni ne finance aucun culte"}]},{"enonce":"La laïcité, est-ce l’athéisme de l’État ?","aide":"Le texte garantit aussi le libre exercice des cultes.","type":"choix","options":[{"id":"a","texte":"Non : l’État n’a pas d’opinion sur Dieu"},{"id":"b","texte":"Oui, mais seulement à l’école"},{"id":"c","texte":"Oui, depuis 1905"},{"id":"d","texte":"Oui : l’État est athée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15","m17","m20"]},"explication":"L’État ne **reconnaît**, ne **salarie** et ne **subventionne** aucun culte : c’est la **séparation**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Trois piliers : **liberté de conscience**, **séparation**, **égalité**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La laïcité n’est **pas** l’athéisme d’État : l’État n’a pas d’opinion sur Dieu et garantit le libre exercice des cultes."}]$ex$::jsonb),
  ('65e0d920-687e-574f-8faf-8c28b3d725cd'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où s’applique la loi de 2004 ?","competence":"lire-tableau","situation":"La loi du 15 mars 2004 interdit les signes religieux ostensibles aux élèves, mais pas partout. Un tableau précise les lieux concernés.","documents":[{"id":"lieux","type":"tableau","titre":"La loi de 2004, lieu par lieu","colonnes":["Le lieu","La loi s’applique-t-elle ?"],"lignes":[["École, collège, lycée publics","Oui"],["Université","Non"],["La rue","Non"],["Établissement privé sous contrat","Non"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"Touche la case qui indique le seul lieu où la loi s’applique.","aide":"Cherche le « Oui ».","type":"zone","document":"lieux","multiple":false},{"enonce":"Sur les quatre lieux du tableau, dans combien la loi de 2004 ne s’applique-t-elle PAS ?","aide":"Compte les « Non ».","type":"nombre","unite":"lieux"},{"enonce":"Un enseignant d’un collège public peut-il manifester ses convictions religieuses en classe ?","aide":"La neutralité s’applique dans l’exercice des fonctions.","type":"choix","options":[{"id":"a","texte":"Oui : c’est sa liberté d’expression"},{"id":"b","texte":"Oui, mais seulement le matin"},{"id":"c","texte":"Non : les agents publics sont neutres dans l’exercice de leurs fonctions"},{"id":"d","texte":"Non, même dans sa vie privée"}],"multiple":false},{"enonce":"Quel régime particulier est toujours en vigueur en Alsace-Moselle ?","aide":"Ces régions étaient allemandes en 1905.","type":"texte","placeholder":"Un nom"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"La loi du 15 mars 2004 ne s’applique qu’à l’**école, au collège et au lycée publics**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 lieux","explication":"Elle ne s’applique pas à l’**université**, à la **rue** et aux **établissements privés sous contrat** : **3 lieux** sur 4."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les agents publics sont **neutres dans l’exercice de leurs fonctions**, pas dans leur vie privée."},{"cle":{"type":"texte","acceptes":["concordat","le concordat"]},"affichage":"concordat","explication":"Le **Concordat** y est toujours en vigueur : la laïcité n’y est pas parfaitement uniforme."}]$ex$::jsonb),
  ('65e0d920-687e-574f-8faf-8c28b3d725cd'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un débat sur la laïcité","competence":"argumenter","situation":"En classe, Sacha répète une idée entendue autour de lui. Maya la corrige. Le dialogue est écrit pour l’exercice.","documents":[{"id":"debat","type":"dialogue","modele":"bulles","titre":"Un débat en classe","participants":[{"nom":"Sacha","emoji":"👦","cote":"gauche"},{"nom":"Maya","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Sacha","texte":"Ma cousine dit que la laïcité, c’est interdire les religions."},{"qui":"Maya","texte":"Non : l’État est neutre, mais la loi de 1905 garantit aussi le libre exercice des cultes."},{"qui":"Sacha","texte":"Et en Alsace-Moselle, c’est pareil ?"},{"qui":"Maya","texte":"Pas tout à fait : ces régions étaient allemandes en 1905, le Concordat y est resté."}],"source":"Dialogue écrit pour l’exercice."},{"id":"neutralite","type":"tableau","titre":"Qui doit la neutralité ?","colonnes":["La personne","Son obligation"],"lignes":[["Agents publics (enseignants, policiers, employés de mairie)","?"],["Usagers d’un service public","Libres, sauf exception prévue par la loi"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"Touche le mot qui exprime l’idée fausse de Sacha.","aide":"C’est le verbe qui dit ce que la laïcité ne fait pas.","type":"zone","document":"debat","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » pour les agents publics ?","aide":"Regarde la situation des usagers, par contraste.","type":"choix","options":[{"id":"a","texte":"Libres de manifester leurs convictions en service"},{"id":"b","texte":"Neutres dans l’exercice de leurs fonctions, pas dans leur vie privée"},{"id":"c","texte":"Aucune obligation"},{"id":"d","texte":"Neutres partout, tout le temps"}],"multiple":false},{"enonce":"Pourquoi l’Alsace-Moselle a-t-elle gardé le Concordat ?","aide":"Maya donne la raison dans sa dernière réplique.","type":"choix","options":[{"id":"a","texte":"Parce que la loi de 1905 l’y autorise explicitement"},{"id":"b","texte":"Parce qu’elle était allemande en 1905"},{"id":"c","texte":"Parce qu’elle a refusé la loi"},{"id":"d","texte":"Parce qu’elle est plus religieuse"}],"multiple":false},{"enonce":"Trie ces affirmations : idée fausse ou idée juste sur la laïcité.","aide":"La loi de 1905 a deux faces.","type":"categories","categories":[{"id":"c0","texte":"Idée fausse"},{"id":"c1","texte":"Idée juste"}],"items":[{"id":"i0","texte":"Un usager d’un service public est libre, sauf exception prévue par la loi"},{"id":"i1","texte":"On ne peut porter aucun signe religieux dans la rue"},{"id":"i2","texte":"La laïcité protège chaque croyant, et l’incroyant de toutes les croyances"},{"id":"i3","texte":"L’État n’a pas d’opinion sur Dieu"},{"id":"i4","texte":"La loi de 1905 ne garantit que la neutralité de l’État"},{"id":"i5","texte":"L’État est athée"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"La laïcité n’**interdit** pas les religions : elle garantit le libre exercice des cultes."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les agents publics sont **neutres dans l’exercice de leurs fonctions**, pas dans leur vie privée."},{"cle":{"type":"choix","ids":["b"]},"explication":"La loi de 1905 est née quand l’Alsace-Moselle était **allemande** : le Concordat y est resté."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"La laïcité est un **principe d’organisation** : elle protège chaque croyant du pouvoir des autres croyances, et l’incroyant de toutes."}]$ex$::jsonb),
  ('0a6e3825-1d5a-515e-8b5d-447301b8b554'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La journée numérique d’Ilan","competence":"analyser-document","situation":"Ilan, 14 ans, a laissé des traces numériques tout au long de sa journée. Certaines viennent de lui, d’autres non.","documents":[{"id":"journee","type":"tableau","titre":"Les traces d’Ilan","colonnes":["Heure","Ce qui se passe"],"lignes":[["8 h","Ilan publie une photo de son petit-déjeuner."],["12 h","Une amie le tague sur une photo de classe."],["15 h","Son application de sport enregistre sa position."],["20 h","Il tape des recherches sur un moteur de recherche."]],"enteteLignes":true,"source":"Journée imaginée pour l’exercice."}],"questions":[{"enonce":"Touche la ligne où une trace est laissée par quelqu’un d’autre qu’Ilan.","aide":"Cherche l’heure où une amie le tague.","type":"zone","document":"journee","multiple":false},{"enonce":"Classe chaque trace selon qui la produit.","aide":"Trois couches : publier, être publié, être enregistré.","type":"categories","categories":[{"id":"c0","texte":"Ce que je publie"},{"id":"c1","texte":"Ce que d’autres publient"},{"id":"c2","texte":"Ce que les services enregistrent"}],"items":[{"id":"i0","texte":"Ma position enregistrée par une appli"},{"id":"i1","texte":"Mes recherches sur un moteur"},{"id":"i2","texte":"Ma photo de profil"},{"id":"i3","texte":"Un article du journal du collège qui parle de moi"},{"id":"i4","texte":"Une amie qui me tague sur une photo"},{"id":"i5","texte":"Un commentaire que j’écris sous une vidéo"}]},{"enonce":"Quel article du Code civil protège la vie privée ?","aide":"Il protège le domicile, la santé, la vie sentimentale, les convictions et l’image.","type":"choix","options":[{"id":"a","texte":"L’article 225"},{"id":"b","texte":"L’article 1"},{"id":"c","texte":"L’article 11"},{"id":"d","texte":"L’article 9"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Quand une amie le tague, c’est un contenu publié par **d’autres** sur lui, sans qu’il l’ait choisi."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c2","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"L’identité numérique a **trois couches** : ce qu’on publie, ce que d’autres publient sur nous, ce que les services **enregistrent** sans qu’on le voie."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’**article 9 du Code civil** protège la vie privée."}]$ex$::jsonb),
  ('0a6e3825-1d5a-515e-8b5d-447301b8b554'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mélissa et l’application","competence":"analyser-document","situation":"Mélissa a 14 ans et veut s’inscrire sur une application. Son frère Hugo lui explique ce que dit la loi. La conversation est écrite pour l’exercice.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Conversation de Mélissa et de Hugo","participants":[{"nom":"Mélissa","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mélissa","texte":"L’appli demande mon accord pour utiliser mes données. J’ai 14 ans, je peux le donner seule ?"},{"qui":"Hugo","texte":"Non, avant l’âge du consentement autonome, il faut l’accord d’un parent."},{"qui":"Mélissa","texte":"Et si je veux ensuite voir ou effacer mes données ?"},{"qui":"Hugo","texte":"Le RGPD te donne des droits, et tu peux saisir la CNIL."}],"source":"Dialogue écrit pour l’exercice."},{"id":"droits","type":"tableau","titre":"Les droits du RGPD","colonnes":["Le droit","Ce qu’il permet"],"lignes":[["Accès","Savoir quelles données sont détenues"],["Rectification","?"],["Effacement","?"],["Opposition","?"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"À partir de quel âge peut-on consentir seul au traitement de ses données en France ?","aide":"Mélissa n’a pas encore cet âge.","type":"nombre","unite":"ans"},{"enonce":"Que doit faire Mélissa, qui a 14 ans, pour s’inscrire ?","aide":"Elle a moins de 15 ans.","type":"choix","options":[{"id":"a","texte":"Rien : l’appli est gratuite"},{"id":"b","texte":"Obtenir l’accord d’un parent"},{"id":"c","texte":"Mentir sur son âge"},{"id":"d","texte":"Attendre 18 ans"}],"multiple":false},{"enonce":"Associe chaque droit du RGPD à ce qu’il permet.","aide":"Le RGPD est entré en application en 2018.","type":"association","gauche":[{"id":"g0","texte":"Accès"},{"id":"g1","texte":"Rectification"},{"id":"g2","texte":"Effacement"},{"id":"g3","texte":"Opposition"}],"droite":[{"id":"d0","texte":"Demander leur suppression"},{"id":"d1","texte":"Refuser un usage de ses données"},{"id":"d2","texte":"Consulter ses données"},{"id":"d3","texte":"Les corriger"}]},{"enonce":"Quelle autorité française veille à la protection des données personnelles ?","aide":"Elle est citée dans la dernière réplique de Hugo.","type":"texte","placeholder":"Un sigle"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 ans","explication":"En France, on consent seul à **15 ans** ; en dessous, il faut l’accord d’un parent."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avant 15 ans, il faut l’**accord d’un parent** pour que le service traite ses données."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"**Accès** : consulter ; **rectification** : corriger ; **effacement** : le « droit à l’oubli » ; **opposition** : refuser un usage."},{"cle":{"type":"texte","acceptes":["cnil","la cnil"]},"affichage":"cnil","explication":"C’est la **CNIL**, qui peut être saisie en cas de problème."}]$ex$::jsonb),
  ('0a6e3825-1d5a-515e-8b5d-447301b8b554'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Supprimer ne suffit pas","competence":"argumenter","situation":"Une élève a publié une vidéo moqueuse à 13 ans, puis l’a supprimée. Trois ans plus tard, elle ressurgit. Le chemin de la vidéo est schématisé.","documents":[{"id":"chemin","type":"chaine","titre":"Le chemin d’une publication","disposition":"colonne","noeuds":[{"id":"z1","texte":"Je publie une vidéo"},{"id":"z2","texte":"Un contact en fait une capture"},{"id":"z3","texte":"La capture est partagée et archivée"},{"id":"z4","texte":"Je supprime ma publication"},{"id":"z5","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]},{"id":"temoin","type":"texte","genre":"lettre","titre":"Le témoignage de Camille","blocs":["J’ai supprimé ma vidéo depuis longtemps. Pourtant, quelqu’un l’a retrouvée et l’a montrée à un employeur potentiel pour mon stage."],"source":"Témoignage écrit pour l’exercice."}],"questions":[{"enonce":"Touche l’étape qui explique pourquoi supprimer sa publication ne suffit pas.","aide":"Quelqu’un d’autre en garde une trace.","type":"zone","document":"chemin","multiple":false},{"enonce":"Que devrait indiquer le dernier « ? » ?","aide":"Relis la ligne « permanence » de la leçon.","type":"choix","options":[{"id":"a","texte":"L’image a disparu pour toujours"},{"id":"b","texte":"L’image est devenue légale"},{"id":"c","texte":"L’image existe toujours ailleurs, copiée ou archivée"},{"id":"d","texte":"L’image est désormais privée"}],"multiple":false},{"enonce":"Trie ces réflexes : à adopter ou à éviter.","aide":"Pense à ce qui protège la vie privée, et à ce qui la menace.","type":"categories","categories":[{"id":"c0","texte":"À adopter"},{"id":"c1","texte":"À éviter"}],"items":[{"id":"i0","texte":"Poster sans réfléchir une photo de quelqu’un d’autre"},{"id":"i1","texte":"Diffuser une image intime"},{"id":"i2","texte":"Réfléchir avant de publier la photo d’un camarade"},{"id":"i3","texte":"Utiliser des mots de passe distincts"},{"id":"i4","texte":"Régler la confidentialité de ses comptes"}]},{"enonce":"Pourquoi une publication de collège peut-elle ressortir dix ans plus tard ?","aide":"Pense au chemin schématisé.","type":"choix","options":[{"id":"a","texte":"Parce que le contenu a pu être copié et archivé"},{"id":"b","texte":"Parce que seul l’auteur peut la retrouver"},{"id":"c","texte":"Parce qu’internet efface tout au bout de dix ans"},{"id":"d","texte":"Parce que la loi interdit de supprimer"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **capture d’écran** est une copie que l’on ne contrôle plus : supprimer l’original ne la fait pas disparaître."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le contenu est **copiable** et **archivé** : supprimer ne supprime pas les captures d’écran."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0"}},"explication":"Réglages de confidentialité, mots de passe distincts et **réflexion avant publication** protègent. **Diffuser une image intime** est un délit lourdement puni."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un contenu **copié** et **archivé** peut ressortir longtemps après, par exemple devant un employeur."}]$ex$::jsonb),
  ('c501cbf8-0f85-5230-811d-49eb1be32d43'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le droit de dire","competence":"analyser-texte","situation":"L’article 11 de la Déclaration de 1789 est au cœur de la liberté d’expression. Lis cette version adaptée pour la classe.","documents":[{"id":"art11","type":"texte","genre":"source","titre":"Article 11 (adapté)","blocs":["La libre communication des pensées et des opinions est un droit très précieux. Chacun peut parler, écrire et publier librement, mais doit répondre des abus de cette liberté dans les cas fixés par la loi."],"source":"D’après l’article 11 de la Déclaration des droits de l’homme et du citoyen de 1789 (texte adapté pour l’exercice)."}],"questions":[{"enonce":"Touche les trois verbes qui disent ce que chacun peut faire librement.","aide":"Ils sont dans la deuxième phrase, après « Chacun peut ».","type":"zone","document":"art11","multiple":true},{"enonce":"Quelle loi du 29 juillet 1881 encadre la liberté de la presse et ses limites ?","aide":"Elle est citée dans la leçon avec la Déclaration de 1789.","type":"choix","options":[{"id":"a","texte":"La loi sur le vote des femmes"},{"id":"b","texte":"La loi sur le service civique"},{"id":"c","texte":"La loi sur la liberté de la presse"},{"id":"d","texte":"La loi sur la laïcité"}],"multiple":false},{"enonce":"Associe chaque délit à sa définition.","aide":"Pour l’une, il y a un fait précis ; pour l’autre, non.","type":"association","gauche":[{"id":"g0","texte":"Injure"},{"id":"g1","texte":"Diffamation"},{"id":"g2","texte":"Apologie du terrorisme"}],"droite":[{"id":"d0","texte":"Un fait faux qui porte atteinte à l’honneur"},{"id":"d1","texte":"Une expression outrageante, sans fait précis"},{"id":"d2","texte":"La présentation favorable d’un acte terroriste"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15","m16","m18"]},"explication":"Chacun peut **parler**, **écrire** et **publier** librement, tout en répondant des abus prévus par la loi."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **loi du 29 juillet 1881** pose la liberté de la presse **et** ses limites."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"L’**injure** est outrageante sans fait précis ; la **diffamation** allègue un fait **faux** ; l’**apologie du terrorisme** présente un acte sous un jour favorable."}]$ex$::jsonb),
  ('c501cbf8-0f85-5230-811d-49eb1be32d43'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Sur le forum de la classe","competence":"argumenter","situation":"Noé et Lila discutent de ce qu’on peut écrire sur internet. Leur échange est écrit pour l’exercice.","documents":[{"id":"forum","type":"dialogue","modele":"bulles","titre":"Discussion à propos d’internet","participants":[{"nom":"Noé","emoji":"👦","cote":"gauche"},{"nom":"Lila","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Noé","texte":"Sur internet je peux tout écrire : avec mon pseudo, personne ne sait qui je suis."},{"qui":"Lila","texte":"Faux. Ton adresse IP permet de te retrouver, et la loi s’applique de la même façon en ligne."},{"qui":"Noé","texte":"Et si je ne fais que partager un message qui n’est pas de moi ?"},{"qui":"Lila","texte":"Partager, c’est diffuser : tu es concerné aussi."}],"source":"Dialogue écrit pour l’exercice."}],"questions":[{"enonce":"Touche le mot qui exprime la fausse protection dont parle Noé.","aide":"Il pense qu’un faux nom suffit à ne pas être retrouvé.","type":"zone","document":"forum","multiple":false},{"enonce":"Qu’est-ce qui permet de retrouver l’auteur d’un message posté sous pseudonyme ?","aide":"Lila le dit dans sa première réponse.","type":"choix","options":[{"id":"a","texte":"Son nombre d’abonnés"},{"id":"b","texte":"La couleur de l’écran"},{"id":"c","texte":"L’adresse IP"},{"id":"d","texte":"Le prénom de ses amis"}],"multiple":false},{"enonce":"Partager un contenu illicite, est-ce engager sa responsabilité ?","aide":"Pense à la dernière réplique de Lila.","type":"choix","options":[{"id":"a","texte":"Non, sauf avec un pseudo"},{"id":"b","texte":"Non : seul l’auteur est responsable"},{"id":"c","texte":"Oui, mais uniquement pour un adulte"},{"id":"d","texte":"Oui : publier, partager ou retweeter, c’est diffuser"}],"multiple":false},{"enonce":"Trie ces propos : protégés ou punis par la loi ?","aide":"La frontière n’est pas entre le poli et l’impoli.","type":"categories","categories":[{"id":"c0","texte":"Protégé"},{"id":"c1","texte":"Puni"}],"items":[{"id":"i0","texte":"Affirmer à tort qu’un camarade a volé"},{"id":"i1","texte":"Appeler à s’en prendre à des personnes à cause de leur religion"},{"id":"i2","texte":"Critiquer une religion ou une idée"},{"id":"i3","texte":"Insulter un camarade dans un commentaire"},{"id":"i4","texte":"Critiquer une loi"},{"id":"i5","texte":"Se moquer d’un parti politique par une caricature"}]}]}$ex$::jsonb,
