  ('c501cbf8-0f85-5230-811d-49eb1be32d43'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une photo qui tourne","competence":"analyser-document","situation":"Dans le groupe de messagerie d’une classe, une photo circule. Chacun a un rôle dans ce qui s’est passé. Le récit est écrit pour l’exercice.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Dans le groupe de la 3e B","blocs":["Tom publie une photo de Yanis endormi en cours, sans lui demander son accord.","Clara écrit : « Yanis a volé le portable de Maëlle », alors que c’est faux.","Hugo ajoute : « T’es vraiment nul ». Enfin, Inès partage la photo à tout le collège."],"source":"Récit écrit pour l’exercice."},{"id":"qualif","type":"tableau","titre":"Qui a fait quoi ?","colonnes":["Auteur","Acte"],"lignes":[["Tom","Diffuse la photo sans l’accord de Yanis"],["Clara","Affirme un fait faux qui porte atteinte à l’honneur"],["Hugo","Écrit une expression outrageante, sans fait précis"],["Inès","Partage la photo à tout le collège"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice."}],"questions":[{"enonce":"Touche les deux mots qui montrent que Clara commet une diffamation.","aide":"Elle avance un fait, et il est inexact.","type":"zone","document":"recit","multiple":true},{"enonce":"Associe chaque auteur à la qualification de son acte.","aide":"Regarde ce que fait chacun dans le tableau.","type":"association","gauche":[{"id":"g0","texte":"Tom"},{"id":"g1","texte":"Clara"},{"id":"g2","texte":"Hugo"},{"id":"g3","texte":"Inès"}],"droite":[{"id":"d0","texte":"Atteinte au droit à l’image"},{"id":"d1","texte":"Diffamation"},{"id":"d2","texte":"Diffusion : celui qui partage est concerné"},{"id":"d3","texte":"Injure"}]},{"enonce":"Où passe la frontière de la liberté d’expression dans cette histoire ?","aide":"On peut critiquer une idée, pas s’en prendre à une personne.","type":"choix","options":[{"id":"a","texte":"Entre le poli et l’impoli"},{"id":"b","texte":"Entre les adultes et les élèves"},{"id":"c","texte":"Entre l’idée et la personne"},{"id":"d","texte":"Entre internet et la vie réelle"}],"multiple":false},{"enonce":"Peut-on diffuser la photo de quelqu’un sans son accord, si elle n’est pas insultante ?","aide":"Relis l’encadré sur le droit à l’image.","type":"choix","options":[{"id":"a","texte":"Oui : une photo neutre n’est pas un problème"},{"id":"b","texte":"Oui, si elle est drôle"},{"id":"c","texte":"Non : le droit à l’image protège aussi les images neutres"},{"id":"d","texte":"Oui, entre élèves de la même classe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m27"]},"explication":"Clara avance un fait précis (« volé ») qui est **faux** : c’est une **diffamation**."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"**Tom** viole le droit à l’image, **Clara** diffame, **Hugo** injurie et **Inès**, en partageant, **diffuse** à son tour."},{"cle":{"type":"choix","ids":["c"]},"explication":"La frontière est entre l’**idée** et la **personne**, pas entre le poli et l’impoli."},{"cle":{"type":"choix","ids":["c"]},"explication":"Diffuser une image **sans l’accord** de la personne est interdit, **même** si elle n’est pas insultante."}]$ex$::jsonb),
  ('c5d2f957-2a69-5c98-a5a8-e8e4b48c1da6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Information, opinion, rumeur ou pub ?","competence":"analyser-document","situation":"Un professeur documentaliste présente quatre contenus croisés dans une même journée. Il faut dire de quelle nature est chacun.","documents":[{"id":"contenus","type":"tableau","titre":"Quatre contenus","colonnes":["Contenu","Ce qu’on lit"],"lignes":[["A","Article signé et daté qui rapporte l’ouverture d’un gymnase, avec la source citée."],["B","Commentaire : « Ce film est nul. »"],["C","« Il paraît que le collège ferme, tout le monde le dit. »"],["D","Spot : « Achetez ce produit, vous allez adorer ! »"]],"enteteLignes":true,"source":"Contenus imaginés pour l’exercice."}],"questions":[{"enonce":"Touche le contenu qui est une information au sens journalistique.","aide":"Cherche un fait vérifié, sourcé, daté et signé.","type":"zone","document":"contenus","multiple":false},{"enonce":"Associe chaque contenu à sa nature.","aide":"Une opinion n’a pas à être vraie ; une rumeur n’a pas de source.","type":"association","gauche":[{"id":"g0","texte":"A"},{"id":"g1","texte":"B"},{"id":"g2","texte":"C"},{"id":"g3","texte":"D"}],"droite":[{"id":"d0","texte":"Une opinion"},{"id":"d1","texte":"Une information"},{"id":"d2","texte":"Une publicité"},{"id":"d3","texte":"Une rumeur"}]},{"enonce":"Qu’est-ce qu’une infox ?","aide":"Le mot vient de « information » et « intoxication ».","type":"choix","options":[{"id":"a","texte":"Une opinion personnelle"},{"id":"b","texte":"Une publicité"},{"id":"c","texte":"Une information vérifiée"},{"id":"d","texte":"Une fausse information diffusée volontairement"}],"multiple":false}]}$ex$::jsonb,
