   $ex${"titre":"Dans la bulle de Chloé","competence":"analyser-document","situation":"Chloé s’informe presque uniquement sur les réseaux. Elle a compté les sources qui lui sont apparues pendant un mois. Le cycle de l’algorithme est schématisé.","documents":[{"id":"bulle","type":"chaine","titre":"Le cycle de la bulle de filtre","disposition":"cycle","noeuds":[{"id":"z1","texte":"Je regarde un contenu"},{"id":"z2","texte":"L’algorithme retient ce qui capte l’attention"},{"id":"z3","texte":"Il me propose des contenus semblables"},{"id":"z4","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z1"}]},{"id":"sources","type":"graphique","forme":"barres","titre":"Sources rencontrées par Chloé en un mois","categories":["Même opinion que Chloé","Autres opinions"],"series":[{"nom":"Sources","valeurs":[18,2],"teinte":"violet"}],"axeY":{"titre":"Sources","unite":"nombre","min":0,"max":20,"pas":5},"valeurs":false,"source":"Données imaginées pour l’exercice."}],"questions":[{"enonce":"Que devrait indiquer le dernier « ? » du cycle ?","aide":"Le cycle recommence avec des contenus de plus en plus semblables.","type":"choix","options":[{"id":"a","texte":"L’algorithme s’arrête"},{"id":"b","texte":"Je vois autant d’opinions différentes"},{"id":"c","texte":"Je ne vois plus aucun contenu"},{"id":"d","texte":"Je finis par ne voir que ce qui confirme mes idées"}],"multiple":false},{"enonce":"Touche la catégorie de sources qui domine dans l’univers de Chloé.","aide":"Cherche la barre la plus haute.","type":"zone","document":"sources","multiple":false},{"enonce":"Quelle proportion (en %) des sources de Chloé partage son opinion ?","aide":"18 sources sur 20 au total.","type":"nombre","unite":"%"},{"enonce":"Comment Chloé peut-elle sortir de sa bulle de filtre ?","aide":"Cela demande un effort volontaire.","type":"choix","options":[{"id":"a","texte":"En attendant que l’algorithme change"},{"id":"b","texte":"En allant chercher volontairement d’autres sources"},{"id":"c","texte":"En se désabonnant de toute information"},{"id":"d","texte":"En ne vérifiant plus rien"}],"multiple":false},{"enonce":"Combien de sources indépendantes un journaliste doit-il recouper au minimum ?","aide":"C’est le minimum du recoupement.","type":"choix","options":[{"id":"a","texte":"Aucune, s’il est expérimenté"},{"id":"b","texte":"Deux"},{"id":"c","texte":"Dix"},{"id":"d","texte":"Une"}],"multiple":false}]}$ex$::jsonb,
