  ('af6d8cd6-0bc1-59c5-bcf3-63eb416e675a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce que dit la loi","competence":"analyser-texte","situation":"Le professeur d’EMC distribue un extrait de loi adapté pour la classe. Il s’agit de repérer ce qui définit une discrimination.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"Définition de la discrimination","blocs":["La discrimination est une différence de traitement défavorable, fondée sur un critère interdit par la loi, comme l’origine, le sexe ou le handicap.","Elle est punie de trois ans d’emprisonnement et de 45 000 € d’amende."],"source":"D’après le Code pénal, articles 225-1 et 225-2 (texte adapté pour l’exercice)."}],"questions":[{"enonce":"Touche les trois critères interdits cités dans le texte.","aide":"Ils suivent l’expression « comme l’ ».","type":"zone","document":"loi","multiple":true},{"enonce":"Pendant combien d’années de prison une discrimination est-elle punie au maximum ?","aide":"Lis la dernière phrase du texte.","type":"nombre","unite":"ans"},{"enonce":"Laquelle de ces situations est une discrimination ?","aide":"Il faut un traitement défavorable, un critère interdit et un domaine protégé.","type":"choix","options":[{"id":"a","texte":"Choisir un ami selon ses goûts"},{"id":"b","texte":"Ne pas inviter quelqu’un à son anniversaire"},{"id":"c","texte":"Refuser un emploi à un candidat sans le diplôme exigé"},{"id":"d","texte":"Refuser de louer un logement à quelqu’un à cause de son nom"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m20","m23"]},"explication":"**Origine**, **sexe** et **handicap** font partie des critères interdits, avec la religion, l’âge ou l’apparence physique."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 ans","explication":"Jusqu’à **3 ans d’emprisonnement** et **45 000 €** d’amende pour un particulier ou une entreprise."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **nom** renvoie à l’origine, critère interdit ; le **logement** est un domaine protégé. Le diplôme, lui, est un critère **pertinent**."}]$ex$::jsonb),
  ('af6d8cd6-0bc1-59c5-bcf3-63eb416e675a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Directe, indirecte ou légitime ?","competence":"analyser-document","situation":"Une conseillère de la mission locale présente à des lycéens plusieurs cas tirés de situations réelles. Il faut les classer.","documents":[{"id":"cas","type":"tableau","titre":"Quatre situations","colonnes":["N°","La situation"],"lignes":[["1","Une entreprise écarte un candidat qui n’a pas le diplôme exigé pour le poste."],["2","Un propriétaire refuse de louer à une famille à cause de son nom."],["3","Un employeur refuse un candidat sans permis alors que le poste demande de conduire."],["4","Un club refuse une joueuse à cause de son handicap, alors que l’activité peut être adaptée."]],"enteteLignes":true,"source":"Cas imaginés pour l’exercice."},{"id":"reglement","type":"texte","genre":"consigne","titre":"Un règlement de recrutement","blocs":["« Pour devenir agent d’accueil, il faut mesurer au moins 1,80 m. » Cette taille n’a aucun lien avec les missions du poste, mais elle écarte surtout des femmes."],"source":"Règlement imaginé pour l’exercice."}],"questions":[{"enonce":"Classe chaque situation du tableau.","aide":"Un critère pertinent pour le poste est légitime ; un critère interdit non.","type":"categories","categories":[{"id":"c0","texte":"Discrimination"},{"id":"c1","texte":"Différence légitime"}],"items":[{"id":"i0","texte":"Situation 2"},{"id":"i1","texte":"Situation 4"},{"id":"i2","texte":"Situation 1"},{"id":"i3","texte":"Situation 3"}]},{"enonce":"Le règlement sur la taille minimale est une discrimination…","aide":"La règle est neutre en apparence, mais défavorise un groupe.","type":"choix","options":[{"id":"a","texte":"Légitime"},{"id":"b","texte":"Directe"},{"id":"c","texte":"Indirecte"},{"id":"d","texte":"Inexistante"}],"multiple":false},{"enonce":"Le recruteur dit : « Je n’ai pas voulu discriminer, ça m’est venu naturellement. » Est-ce une défense valable ?","aide":"Le droit juge le résultat de l’acte.","type":"choix","options":[{"id":"a","texte":"Non, sauf s’il a des excuses écrites"},{"id":"b","texte":"Oui : sans intention, pas de délit"},{"id":"c","texte":"Oui, si c’est la première fois"},{"id":"d","texte":"Non : le droit regarde ce qui a été fait, pas l’intention"}],"multiple":false},{"enonce":"Quelle autorité indépendante peut être saisie gratuitement par toute personne qui s’estime discriminée ?","aide":"Son nom commence par « Défenseur ».","type":"texte","placeholder":"Nom de l’autorité"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Les situations **1** et **3** reposent sur un critère **pertinent** (diplôme, permis). Les situations **2** (nom) et **4** (handicap) reposent sur un critère **interdit**."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est une discrimination **indirecte** : une règle neutre en apparence qui défavorise en fait un groupe (ici les femmes)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le droit ne demande pas ce que la personne a **voulu** faire, mais ce qu’elle a **fait** : on peut discriminer sans se penser raciste ou sexiste."},{"cle":{"type":"texte","acceptes":["defenseur des droits","le defenseur des droits"]},"affichage":"défenseur des droits","explication":"C’est le **Défenseur des droits**, saisi gratuitement par toute personne."}]$ex$::jsonb),
  ('af6d8cd6-0bc1-59c5-bcf3-63eb416e675a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le test des deux candidatures","competence":"argumenter","situation":"Une association envoie 100 candidatures identiques, à une seule différence près : le nom sur le CV. Elle compare les réponses positives. La responsable des ressources humaines répond par courrier, écrit pour l’exercice.","documents":[{"id":"testing","type":"graphique","forme":"barres","titre":"Réponses positives sur 100 candidatures","categories":["Candidature A","Candidature B"],"series":[{"nom":"Réponses positives","valeurs":[42,21],"teinte":"violet"}],"axeY":{"titre":"Réponses positives","unite":"sur 100","min":0,"max":50,"pas":10},"valeurs":false,"source":"Résultats imaginés pour l’exercice."},{"id":"courrier","type":"texte","genre":"lettre","titre":"Réponse de la direction","blocs":["Nous n’avons jamais eu l’intention de discriminer. Nous cherchions simplement un profil qui « corresponde à notre équipe »."],"source":"Courrier écrit pour l’exercice."}],"questions":[{"enonce":"Touche la candidature qui reçoit le moins de réponses positives.","aide":"Compare la hauteur des deux barres.","type":"zone","document":"testing","multiple":false},{"enonce":"Quel est l’écart de réponses positives entre les deux candidatures ?","aide":"Soustrais 21 à 42.","type":"nombre","unite":"réponses"},{"enonce":"À quoi sert le « testing » ?","aide":"Les deux CV sont identiques sauf sur un critère.","type":"choix","options":[{"id":"a","texte":"À sanctionner l’association"},{"id":"b","texte":"À tester les compétences du candidat"},{"id":"c","texte":"À comparer deux candidatures identiques, sauf sur un critère, pour prouver une discrimination"},{"id":"d","texte":"À choisir le meilleur candidat"}],"multiple":false},{"enonce":"La direction dit n’avoir « jamais eu l’intention » de discriminer. Peut-elle être condamnée ?","aide":"Relis la dernière phrase de la leçon sur les sanctions.","type":"choix","options":[{"id":"a","texte":"Non, car elle a écrit un courrier poli"},{"id":"b","texte":"Oui, mais seulement si elle l’avoue"},{"id":"c","texte":"Non : sans intention, aucune faute"},{"id":"d","texte":"Oui : l’intention n’est pas nécessaire, le résultat suffit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"La candidature **B** reçoit 21 réponses positives, deux fois moins que la A."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21 réponses","explication":"42 − 21 = **21 réponses** d’écart. Les deux CV étant identiques, la différence vient du critère comparé."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **testing** compare deux candidatures identiques sauf sur un critère : c’est une preuve **admise en justice**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il n’est **pas nécessaire** d’avoir voulu discriminer : l’acte, lui, suffit pour qu’il y ait délit."}]$ex$::jsonb),
