   $ex${"titre":"Une cyberattaque contre un hôpital","competence":"analyser-document","situation":"Un article écrit pour l’exercice raconte une attaque informatique contre un hôpital. Un tableau présente trois cadres collectifs de la défense.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Hôpital paralysé","blocs":["Un matin, les ordinateurs d’un hôpital sont bloqués par une cyberattaque. Les dossiers des patients sont inaccessibles. Les pompiers et les secours mettent en place une cellule de crise.","Aucune armée n’a franchi de frontière : un logiciel a suffi."],"source":"Article imaginé pour l’exercice."},{"id":"cadres","type":"tableau","titre":"Les cadres collectifs","colonnes":["L’organisation","Son rôle"],"lignes":[["OTAN (1949)","Alliance militaire : une attaque contre un membre engage les autres"],["Union européenne","Politique de sécurité et de défense commune"],["ONU","Opérations de maintien de la paix, « casques bleus »"]],"enteteLignes":true,"source":"Tableau de synthèse écrit pour l’exercice."}],"questions":[{"enonce":"Touche le mot qui désigne le type de menace qui frappe l’hôpital.","aide":"C’est une attaque par logiciel.","type":"zone","document":"article","multiple":false},{"enonce":"Touche le mot qui désigne ceux qui relèvent de la sécurité civile.","aide":"Ils interviennent pour les secours et les catastrophes.","type":"zone","document":"article","multiple":false},{"enonce":"Pourquoi la défense ne concerne-t-elle pas que les militaires ?","aide":"Relis la dernière phrase de l’article.","type":"choix","options":[{"id":"a","texte":"Parce que la défense est privée"},{"id":"b","texte":"Parce que l’armée n’existe plus"},{"id":"c","texte":"Parce que les menaces touchent aussi les réseaux, les secours et l’économie"},{"id":"d","texte":"Parce que seuls les civils décident"}],"multiple":false},{"enonce":"Associe chaque organisation à son rôle.","aide":"Regarde le tableau.","type":"association","gauche":[{"id":"g0","texte":"OTAN"},{"