t":"droits","multiple":false},{"enonce":"Touche la case du droit qui permet de s’adresser au Parlement européen.","aide":"Cherche le mot « pétition ».","type":"zone","document":"droits","multiple":false},{"enonce":"Que signifie « la citoyenneté européenne s’ajoute à la citoyenneté nationale » pour Marta ?","aide":"Une citoyenneté en plus, pas à la place.","type":"choix","options":[{"id":"a","texte":"Elle devient française"},{"id":"b","texte":"Elle reste espagnole et gagne des droits en France"},{"id":"c","texte":"Elle n’a aucun droit nouveau"},{"id":"d","texte":"Elle perd sa nationalité espagnole"}],"multiple":false}]}$ex$::jsonb,
