   $ex${"titre":"Les dimanches de Lucía","competence":"comprendre-langue","situation":"Lucía écrit à son correspondant français pour lui raconter comment se passent ses dimanches en famille.","documents":[{"id":"domingos","type":"texte","genre":"lettre","titre":"Los domingos de Lucía","blocs":["Hola, soy Lucía. Los domingos suelo levantarme tarde. Siempre desayuno churros con mi abuelo. A veces vamos al parque y nunca me aburro."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Que signifie « suelo levantarme tarde » ?","aide":"Soler + infinitif dit l’habitude.","type":"choix","options":[{"id":"a","texte":"Je me suis levée tard hier"},{"id":"b","texte":"Je me lève très tôt"},{"id":"c","texte":"J’ai l’habitude de me lever tard"},{"id":"d","texte":"Je vais me lever tard demain"}],"multiple":false},{"enonce":"Touche les **trois marqueurs de fréquence** du texte.","aide":"Ils répondent à la question « combien de fois ? » : toujours, parfois, jamais.","type":"zone","document":"domingos","multiple":true},{"enonce":"Associe chaque marqueur à son sens.","aide":"Le dernier marqueur n’est pas dans le texte : pense à « fréquemment ».","type":"association","gauche":[{"id":"g0","texte":"siempre"},{"id":"g1","texte":"a veces"},{"id":"g2","texte":"nunca"},{"id":"g3","texte":"a menudo"}],"droite":[{"id":"d0","texte":"souvent"},{"id":"d1","texte":"parfois"},{"id":"d2","texte":"jamais"},{"id":"d3","texte":"toujours"}]}]}$ex$::jsonb,
