  ('b946c88b-33f1-55ce-ab95-31c28348ba02'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La routine d’Irene, nageuse","competence":"manier-langue","situation":"Irene, nageuse de quatorze ans, raconte sa semaine à un magazine de son collège. Un tableau résume ses habitudes.","documents":[{"id":"irene","type":"texte","genre":"article","titre":"Mi semana de nadadora","blocs":["Entrenamos de lunes a viernes. Normalmente me levanto a las seis, pero de vez en cuando me quedo en la cama.","Cuando era pequeña, solía nadar solo los sábados. Ahora sigo entrenando cada día y volví a participar en el campeonato el mes pasado."],"source":"Article écrit pour l’exercice"},{"id":"habitos","type":"tableau","titre":"Los hábitos de Irene","colonnes":["Hábito","Frecuencia"],"lignes":[["Entrenar","todos los días"],["Quedarse en la cama","de vez en cuando"],["Comer pasta antes de competir","siempre"],["Llegar tarde","casi nunca"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui dit l’**habitude dans le passé**.","aide":"C’est une forme de soler à l’imparfait.","type":"zone","document":"irene","multiple":false},{"enonce":"Que signifie « volví a participar en el campeonato » ?","aide":"Volver a + infinitif : on refait quelque chose une fois de plus.","type":"choix","options":[{"id":"a","texte":"J’ai de nouveau participé au championnat"},{"id":"b","texte":"Je ne participe plus au championnat"},{"id":"c","texte":"Je participais d’ordinaire au championnat"},{"id":"d","texte":"Je participe toujours au championnat"}],"multiple":false},{"enonce":"Dans le tableau, touche la fréquence de ce qu’Irene ne fait **presque jamais**.","aide":"Cherche la ligne sur le retard.","type":"zone","document":"habitos","multiple":false},{"enonce":"Associe chaque marqueur du tableau à son sens.","aide":"Todos los días embrasse l’ensemble des jours.","type":"association","gauche":[{"id":"g0","texte":"todos los días"},{"id":"g1","texte":"de vez en cuando"},{"id":"g2","texte":"siempre"},{"id":"g3","texte":"casi nunca"}],"droite":[{"id":"d0","texte":"chaque jour, sans exception"},{"id":"d1","texte":"presque jamais"},{"id":"d2","texte":"de temps en temps"},{"id":"d3","texte":"toujours"}]},{"enonce":"Les parents d’Irene ont l’habitude de dîner à neuf heures. Complète.","aide":"Le sujet est « mis padres » : 3e personne du pluriel.","type":"trous","segments":["Mis padres ",0," cenar a las nueve."],"banque":["suele","sueles","suelen","solemos"]}]}$ex$::jsonb,
