   $ex${"titre":"La lettre de Diego","competence":"manier-langue","situation":"Diego écrit à sa cousine Julia depuis sa nouvelle maison. Dans sa lettre, il emploie plusieurs relatives.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Diego","blocs":["Querida Julia:","Mi vecino toca la trompeta de noche, lo que no nos deja dormir.","Mi hermana Rosa, quien vive en Lima, llega mañana. Los primos que viven en Cádiz llegan el domingo.","Un abrazo, Diego"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui reprennent **toute l’idée** de la première partie de la phrase du voisin.","aide":"C’est un pronom neutre en deux mots.","type":"zone","document":"carta","multiple":true},{"enonce":"Dans la lettre, que fait la relative « quien vive en Lima » ?","aide":"Elle est entourée de virgules.","type":"choix","options":[{"id":"a","texte":"Elle distingue Rosa des autres sœurs de Diego"},{"id":"b","texte":"Elle ajoute une information sur Rosa sans la distinguer"},{"id":"c","texte":"Elle exprime un doute à propos de Rosa et du voyage"},{"id":"d","texte":"Elle remplace le sujet de la phrase principale"}],"multiple":false},{"enonce":"Remets en ordre : « Le garçon dont je parle. » La phrase commence par El.","aide":"La préposition de se place avant le relatif.","type":"ordre","items":[{"id":"a","texte":"chico"},{"id":"b","texte":"hablo"},{"id":"c","texte":"El"},{"id":"d","texte":"del que"}]},{"enonce":"Complète avec le bon relatif.","aide":"Cuyo s’accorde avec ce qui est possédé : novela.","type":"trous","segments":["El libro del ",0," te hablé es este. El escritor ",1," novela leí es famoso. Llegó tarde, ",2," me molestó."],"banque":["cuyo","quien","que","cuya","lo que"]},{"enonce":"Range chaque phrase : la relative est-elle déterminative (elle restreint) ou explicative (elle ajoute) ?","aide":"Regarde les virgules.","type":"categories","categories":[{"id":"c0","texte":"Déterminative (elle restreint)"},{"id":"c1","texte":"Explicative (elle ajoute)"}],"items":[{"id":"i0","texte":"Los perros que ladran mucho molestan"},{"id":"i1","texte":"Las chicas que juegan al fútbol entrenan hoy"},{"id":"i2","texte":"Los vecinos, que son simpáticos, nos ayudan"},{"id":"i3","texte":"Mi tía, que vive en Lima, llega mañana"}]}]}$ex$::jsonb,
